import{_ as t,o as r,c as o,a0 as a}from"./chunks/framework.bcCluOOn.js";const p=JSON.parse('{"title":"BrainOS","description":"","frontmatter":{},"headers":[],"relativePath":"platform/brainos.md","filePath":"platform/brainos.md"}'),n={name:"platform/brainos.md"};function i(s,e,l,c,d,g){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="brainos" tabindex="-1">BrainOS <a class="header-anchor" href="#brainos" aria-label="Permalink to &quot;BrainOS&quot;">​</a></h1><p><strong>Status: Prototype v0.2</strong></p><p>BrainOS is an <strong>AI-Native Software Engineering Operating System</strong>.</p><p>While AAYU focuses on translating Intent into software, BrainOS focuses on <strong>Project Intelligence</strong>. It serves as the long-term memory, decision maker, and context builder for the AAYU ecosystem.</p><h2 id="why-brainos" tabindex="-1">Why BrainOS? <a class="header-anchor" href="#why-brainos" aria-label="Permalink to &quot;Why BrainOS?&quot;">​</a></h2><p>Today, AI developers lose context rapidly. After a few chats, the AI forgets the project&#39;s vision, architecture, and previous decisions. A developer spends 30-50% of their time just re-explaining the project state.</p><p>BrainOS solves this by ensuring that: <strong>BrainOS remembers everything about a software project so AI never loses context.</strong></p><h2 id="the-7-layer-architecture" tabindex="-1">The 7-Layer Architecture <a class="header-anchor" href="#the-7-layer-architecture" aria-label="Permalink to &quot;The 7-Layer Architecture&quot;">​</a></h2><p>BrainOS is built on a strict, immutable 7-layer architecture:</p><ol><li><strong>Storage Layer</strong>: Agnostic storage (SQLite, Postgres, Neo4j) managed via a unified API.</li><li><strong>Knowledge Graph</strong>: The heart of BrainOS. All projects, tasks, issues, and rules are nodes and edges in a graph.</li><li><strong>Decision Engine</strong>: Automatically detects conflicts. If a developer tries to modify a &quot;Frozen&quot; rule, the Decision Engine blocks it.</li><li><strong>Context Engine</strong>: Dynamically builds Context Bundles combining Project DNA, active tasks, and architecture rules for AI consumption.</li><li><strong>AI Layer</strong>: Interacts with the LLM.</li><li><strong>Plugins</strong>: Extensions for the OS.</li><li><strong>Applications</strong>: User-facing tools built on BrainOS.</li></ol><h2 id="core-capabilities-v0-2" tabindex="-1">Core Capabilities (v0.2) <a class="header-anchor" href="#core-capabilities-v0-2" aria-label="Permalink to &quot;Core Capabilities (v0.2)&quot;">​</a></h2><ul><li>✅ <strong>Graph Engine</strong>: Centralized Node/Edge creation.</li><li>✅ <strong>Project DNA</strong>: Immutable identities and rules for every software project.</li><li>✅ <strong>Task Scheduler</strong>: CLI dashboard for tracking Open/Blocked/Done tasks.</li><li>✅ <strong>Decision Engine</strong>: <code>brain freeze</code> and <code>brain modify</code> commands that block conflicting changes based on Project DNA.</li><li>✅ <strong>Context Bundle</strong>: Auto-generates a context dump for LLMs.</li></ul><p>BrainOS is a companion project to AAYU. In the future, AAYU Chat will rely heavily on BrainOS to fetch project constraints before generating code.</p>',13)])])}const u=t(n,[["render",i]]);export{p as __pageData,u as default};
